                self.roles[name] = self.roles[name].union(self.roles.get(inherited_role, set()))
    def _get_role_actions(self, role):
        role_actions = self.roles.get(role, set())
        for parent_role in self._get_inherited_roles(role):
            role_actions = role_actions.union(self._get_role_actions(parent_role))
        return role_actions
    def _get_inherited_roles(self, role):
        inherited_roles = set()
        stack = [role]
        while stack:
            current_role = stack.pop()
            if current_role in self.roles:
                inherited_roles.add(current_role)
                stack.extend(self._get_inherited_roles(current_role))
        return inherited_roles

