class Permissions:
    def __init__(self):
        self.permissions = {"viewer": {"read"}, "editor": {"read", "write"}}

    def allowed(self, role, action):
        if role in self.permissions:
            return action in self.permissions[role]
        return False

    def effective(self, role):
        if role in self.permissions:
            return set(self.permissions[role])
        return set()

    def restrict(self, role, allowed_actions):
        if role in self.permissions:
            return self.permissions[role] & allowed_actions
        return set()
